function isObjectLike(value) {
    return typeof value === "object" && value !== null;
}
function getSource(value) {
    return isObjectLike(value) ? value : null;
}
function getString(value) {
    return typeof value === "string" && value.length > 0 ? value : undefined;
}
function getDetailValue(value) {
    if (typeof value === "string" && value.length > 0) {
        return value;
    }
    if (typeof value === "number" || typeof value === "boolean") {
        return String(value);
    }
    return undefined;
}
function getNestedCause(value) {
    const source = getSource(value);
    if (!source) {
        return undefined;
    }
    return source.cause ?? source.originalError;
}
function formatCauseNode(value) {
    const source = getSource(value);
    if (!source) {
        return String(value);
    }
    const name = getString(source.name);
    const message = getString(source.message);
    const details = [
        ["code", getDetailValue(source.code)],
        ["errno", getDetailValue(source.errno)],
        ["syscall", getDetailValue(source.syscall)],
        ["hostname", getDetailValue(source.hostname)],
        ["host", getDetailValue(source.host)],
        ["address", getDetailValue(source.address)],
        ["port", getDetailValue(source.port)],
    ]
        .filter((entry) => entry[1] !== undefined)
        .map(([key, detailValue]) => `${key}=${detailValue}`);
    const label = message
        ? name && name !== "Error"
            ? `${name}: ${message}`
            : message
        : name ?? String(value);
    return details.length > 0 ? `${label} (${details.join(", ")})` : label;
}
export function formatNestedErrorCause(error) {
    const parts = [];
    const seen = new Set();
    let current = getNestedCause(error);
    while (current !== undefined && current !== null && !seen.has(current)) {
        seen.add(current);
        const formatted = formatCauseNode(current);
        if (formatted && formatted !== parts[parts.length - 1]) {
            parts.push(formatted);
        }
        current = getNestedCause(current);
    }
    return parts.length > 0 ? parts.join(" <- ") : null;
}
export function printNestedErrorCause(error, write = console.error) {
    const cause = formatNestedErrorCause(error);
    if (cause) {
        write(`Cause: ${cause}`);
    }
}
